impl TransformsRecordBuilder {
    /// Builds a [`TransformsRecord`].
    pub fn build(self) -> TransformsRecord {
        TransformsRecord {
            id: self.id,
            state: self.state,
            checkpoint: self.checkpoint,
            documents_processed: self.documents_processed,
            checkpoint_progress: self.checkpoint_progress,
            last_search_time: self.last_search_time,
            changes_last_detection_time: self.changes_last_detection_time,
            create_time: self.create_time,
            version: self.version,
            source_index: self.source_index,
            dest_index: self.dest_index,
            pipeline: self.pipeline,
            project_routing: self.project_routing,
            description: self.description,
            transform_type: self.transform_type,
            frequency: self.frequency,
            max_page_search_size: self.max_page_search_size,
            docs_per_second: self.docs_per_second,
            reason: self.reason,
            search_total: self.search_total,
            search_failure: self.search_failure,
            search_time: self.search_time,
            index_total: self.index_total,
            index_failure: self.index_failure,
            index_time: self.index_time,
            documents_indexed: self.documents_indexed,
            delete_time: self.delete_time,
            documents_deleted: self.documents_deleted,
            trigger_count: self.trigger_count,
            pages_processed: self.pages_processed,
            processing_time: self.processing_time,
            checkpoint_duration_time_exp_avg: self.checkpoint_duration_time_exp_avg,
            indexed_documents_exp_avg: self.indexed_documents_exp_avg,
            processed_documents_exp_avg: self.processed_documents_exp_avg,
        }
    }
}

impl From<TransformsRecordBuilder> for TransformsRecord {
    fn from(builder: TransformsRecordBuilder) -> Self {
        builder.build()
    }
}
